func:
// Init
msg.boiler = {};
return msg;

// logger, usage: log(this, "");
const log = global.get('logger');

// Without the boiler temperature no safe decision can be made: leave everything as it is
if (!isFinite(msg.boiler.temp)) {
    log(this, "Boiler temperature unavailable", "warn");
    node.status({ fill: "red", shape: "ring", text: "No boiler temperature" });
    return null;
}

node.status({});
return msg;

// Heat with the element when the expected solar power next hour is high enough, not on holiday
const b = msg.boiler;
return (b.solar_next_hour > b.solar_threshold && b.holiday !== "on") ? [msg, null] : [null, msg];

// Off at max_temp. Once off, the element only restarts below max_temp - restart_hysteresis
const b = msg.boiler;
return (b.temp >= b.max_temp ||
    (b.element_state !== "on" && b.temp >= b.max_temp - b.restart_hysteresis)) ? [msg, null] : [null, msg];

// Switch the element off when it is on and should be off
const b = msg.boiler;
return (b.element === "off" && b.element_state === "on") ? msg : null;

// Switch the doorstroomboiler off when it is on and should be off
const b = msg.boiler;
return (b.instant === "off" && b.instant_state === "on") ? msg : null;

// Switch the element on when it is off and should be on
const b = msg.boiler;
return (b.element === "on" && b.element_state === "off") ? msg : null;

// Switch the doorstroomboiler on when it is off and should be on
const b = msg.boiler;
return (b.instant === "on" && b.instant_state === "off") ? msg : null;

// Only send a new set point when it differs from the current one
const b = msg.boiler;
if (b.valve.attributes.temperature === b.valve_setpoint) return null;

// Data for 'Set valve': the valve thermostat set point
msg.payload = { data: { temperature: b.valve_setpoint } };
return msg;

// Status
const b = msg.boiler;
const valve = b.valve_setpoint === b.valve_open ? "open" : "closed";
node.status({
    fill: b.element === "on" ? "red" : "grey", shape: "dot",
    text: `${b.temp} °C | element ${b.element} (${b.element_reason}) | doorstroomboiler ${b.instant} | valve ${valve}`
});
return msg;

// Alert
const b = msg.boiler;
return (["unknown", "unavailable"].includes(b.temp_state)) ? msg : null;

// Telegram message
msg.payload = {
    chatId: msg.boiler.telegram_chat_id,
    type: "message",
    content: "Boiler temp unavailable. Please check for working boiler!",
};
return msg;

// Alert
const b = msg.boiler;
return (["unknown", "unavailable"].includes(b.cv_state)) ? msg : null;

// Telegram message
msg.payload = {
    chatId: msg.boiler.telegram_chat_id,
    type: "message",
    content: "CV water temp unavailable. Please check for working boiler!",
};
return msg;

// Alert, heat/cool means the valve thermostat lost its own control
const b = msg.boiler;
return (["unavailable", "heat/cool"].includes(b.valve.state)) ? msg : null;

// Telegram message
msg.payload = {
    chatId: msg.boiler.telegram_chat_id,
    type: "message",
    content: "Valve heatExchanger unavailable. Please check for working boiler!",
};
return msg;

// Alert
const b = msg.boiler;
return (b.element_state === "unavailable") ? msg : null;

// Telegram message
msg.payload = {
    chatId: msg.boiler.telegram_chat_id,
    type: "message",
    content: "Boiler unavailable. Please check for working boiler!",
};
return msg;

// Alert, only when the doorstroomboiler is used
const b = msg.boiler;
return (b.use_instant === "on" && b.instant_state === "unavailable") ? msg : null;

// Telegram message
msg.payload = {
    chatId: msg.boiler.telegram_chat_id,
    type: "message",
    content: "Instant boiler unavailable. Please check for working boiler!",
};
return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;
